/**
 * WebGCS Main Stylesheet
 * Professional styling for drone control interface
 */

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #f0f2f5;
}

.webgcs-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 20px;
}

.webgcs-header {
    background: linear-gradient(135deg, #2c3e50, #34495e);
    color: white;
    padding: 15px 20px;
    border-radius: 8px;
    margin-bottom: 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.webgcs-header h1 {
    margin: 0;
    font-size: 24px;
}

.mavlink-status {
    background: rgba(255, 255, 255, 0.1);
    padding: 5px 10px;
    border-radius: 4px;
    font-size: 14px;
}

.webgcs-main {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
}

section {
    background: white;
    border-radius: 8px;
    padding: 20px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

section h3 {
    margin-top: 0;
    color: #2c3e50;
    border-bottom: 2px solid #3498db;
    padding-bottom: 10px;
}

/* Connection Panel */
.connection-controls {
    display: flex;
    gap: 10px;
    margin-bottom: 15px;
    flex-wrap: wrap;
    align-items: center;
}

.connection-controls label {
    display: flex;
    align-items: center;
    gap: 5px;
    font-weight: 500;
}

.connection-controls input[type="text"] {
    width: 120px;
    padding: 8px;
    border: 1px solid #ddd;
    border-radius: 4px;
}

.connection-status {
    display: flex;
    gap: 15px;
    align-items: center;
    padding: 10px;
    background: #f8f9fa;
    border-radius: 4px;
}

#connection-status {
    font-weight: 500;
    color: #2c3e50;
}

#heartbeat-counter {
    font-weight: 500;
    color: #e74c3c;
}

/* Buttons */
button {
    padding: 10px 16px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 500;
    transition: all 0.3s ease;
}

#connect-btn {
    background: #27ae60;
    color: white;
}

#connect-btn:hover {
    background: #2ecc71;
}

#connect-btn:disabled {
    background: #95a5a6;
    cursor: not-allowed;
}

#disconnect-btn {
    background: #e74c3c;
    color: white;
}

#disconnect-btn:hover:enabled {
    background: #c0392b;
}

#disconnect-btn:disabled {
    background: #95a5a6;
    cursor: not-allowed;
}

/* Flight Controls */
.control-buttons {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    align-items: center;
}

#arm-btn {
    background: #f39c12;
    color: white;
}

#disarm-btn {
    background: #e74c3c;
    color: white;
}

#takeoff-btn, #land-btn, #rtl-btn {
    background: #3498db;
    color: white;
}

#set-mode-btn {
    background: #9b59b6;
    color: white;
}

/* Navigation Panel */
.nav-controls {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    align-items: center;
}

.nav-controls input[type="number"] {
    width: 100px;
    padding: 8px;
    border: 1px solid #ddd;
    border-radius: 4px;
}

#goto-btn {
    background: #27ae60;
    color: white;
}

#clear-btn {
    background: #95a5a6;
    color: white;
}

/* PFD and Map Placeholders */
.pfd-container, .map-container {
    grid-column: span 2;
}

.pfd-display, .map-display {
    height: 300px;
    background: #ecf0f1;
    border: 2px dashed #bdc3c7;
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.pfd-placeholder, .map-placeholder {
    color: #7f8c8d;
    font-size: 16px;
    font-weight: 500;
}

/* Responsive Design */
@media (max-width: 768px) {
    .webgcs-main {
        grid-template-columns: 1fr;
    }

    .pfd-container, .map-container {
        grid-column: span 1;
    }

    .connection-controls, .control-buttons, .nav-controls {
        flex-direction: column;
        align-items: stretch;
    }

    .connection-controls input[type="text"],
    .nav-controls input[type="number"] {
        width: 100%;
    }
}
