/**
 * Professional Primary Flight Display (PFD) - Improved Readability Version
 * Renders all 15 required VFR HUD components with professional aviation styling
 * File size: Must stay under 200 lines per WebGCS PRD
 */

class PrimaryFlightDisplay {
    constructor(canvasId) {
        console.log('PFD: Initializing Professional Primary Flight Display for canvas:', canvasId);
        this.canvas = document.getElementById(canvasId);
        if (!this.canvas) {
            console.error('PFD: Canvas element not found:', canvasId);
            return;
        }

        this.ctx = this.canvas.getContext('2d');
        this.telemetryData = {};
        this.isConnected = false;

        // Professional canvas setup with high DPI support
        const dpr = window.devicePixelRatio || 1;
        this.canvas.width = 800 * dpr;
        this.canvas.height = 600 * dpr;
        this.canvas.style.width = '800px';
        this.canvas.style.height = '600px';
        this.ctx.scale(dpr, dpr);

        // Enable text anti-aliasing for crisp text
        this.ctx.textRenderingOptimization = 'optimizeQuality';
        this.ctx.imageSmoothingEnabled = true;

        console.log('PFD: Professional canvas initialized, logical size: 800x600, pixel ratio:', dpr);

        // Define professional color scheme
        this.colors = {
            background: '#000814',
            text: '#00FFFF',
            textBright: '#FFFFFF', 
            textDim: '#7FB3D3',
            warning: '#FFB000',
            alert: '#FF0000',
            success: '#00FF41',
            panel: 'rgba(0, 20, 40, 0.9)',
            accent: '#0099FF'
        };

        // Initialize telemetry and start render loop
        this.initializeTelemetry();
        this.render();
    }

    initializeTelemetry() {
        const waitForSocket = () => {
            if (window.socket) {
                console.log('PFD: Socket found, setting up telemetry listeners');
                window.socket.on('telemetry_stream', (data) => {
                    this.telemetryData = data;
                    this.isConnected = data.connected;
                });

                window.socket.on('drone_connection_result', (data) => {
                    console.log('PFD: Connection result', data);
                    if (data.success) {
                        this.isConnected = true;
                        this.telemetryData = {
                            connected: true, lat: 0, lon: 0, alt: 0,
                            roll: 0, pitch: 0, yaw: 0, armed: false, mode: 'UNKNOWN'
                        };
                    } else {
                        this.isConnected = false;
                    }
                });
            } else {
                setTimeout(waitForSocket, 100);
            }
        };
        waitForSocket();
    }

    render() {
        // Clear canvas with professional background
        this.ctx.fillStyle = this.colors.background;
        this.ctx.fillRect(0, 0, 800, 600);

        if (!this.isConnected) {
            this.drawDisconnectedState();
        } else {
            // Professional layout with organized instrument placement
            this.drawArtificialHorizon();
            this.drawAircraftSymbol();
            this.drawLeftInstrumentTape();    // Airspeed
            this.drawRightInstrumentTape();   // Altitude  
            this.drawTopInstrumentPanel();    // Heading, modes, status
            this.drawBottomInstrumentPanel(); // Navigation data, battery
        }

        requestAnimationFrame(() => this.render());
    }

    drawDisconnectedState() {
        this.ctx.textAlign = 'center';
        this.ctx.textBaseline = 'middle';

        // Professional disconnected message with better typography
        this.drawText('PRIMARY FLIGHT DISPLAY', 400, 250, 'bold 32px "Courier New", monospace', this.colors.accent);
        this.drawText('DISCONNECTED FROM DRONE', 400, 300, 'bold 20px "Courier New", monospace', this.colors.warning);
        this.drawText('Connect to drone to display flight data', 400, 350, '16px "Arial", sans-serif', this.colors.textDim);

        // Add professional border frame
        this.drawProfessionalBorder();
    }

    drawArtificialHorizon() {
        const centerX = 400, centerY = 300, size = 150;
        const roll = (this.telemetryData.roll || 0) * (Math.PI / 180);
        const pitch = (this.telemetryData.pitch || 0) * 2; // Scale pitch for visibility

        this.ctx.save();
        this.ctx.beginPath();
        this.ctx.arc(centerX, centerY, size, 0, 2 * Math.PI);
        this.ctx.clip();

        this.ctx.translate(centerX, centerY);
        this.ctx.rotate(roll);

        // Sky (professional blue gradient)
        const skyGradient = this.ctx.createLinearGradient(0, -size, 0, size);
        skyGradient.addColorStop(0, '#4A90E2');
        skyGradient.addColorStop(1, '#87CEEB');
        this.ctx.fillStyle = skyGradient;
        this.ctx.fillRect(-size, -size, size*2, size + pitch);

        // Ground (professional brown gradient)  
        const groundGradient = this.ctx.createLinearGradient(0, -size, 0, size);
        groundGradient.addColorStop(0, '#8B4513');
        groundGradient.addColorStop(1, '#A0522D');
        this.ctx.fillStyle = groundGradient;
        this.ctx.fillRect(-size, pitch, size*2, size);

        // Professional horizon line with markers
        this.ctx.strokeStyle = this.colors.textBright;
        this.ctx.lineWidth = 2;
        this.ctx.setLineDash([]);
        this.ctx.beginPath();
        this.ctx.moveTo(-size, pitch);
        this.ctx.lineTo(size, pitch);
        this.ctx.stroke();

        this.ctx.restore();
    }

    drawAircraftSymbol() {
        const centerX = 400, centerY = 300;

        this.ctx.strokeStyle = this.colors.warning;
        this.ctx.lineWidth = 3;
        this.ctx.setLineDash([]);
        this.ctx.beginPath();

        // Professional aircraft symbol
        this.ctx.moveTo(centerX - 40, centerY);
        this.ctx.lineTo(centerX - 10, centerY);
        this.ctx.moveTo(centerX + 10, centerY);
        this.ctx.lineTo(centerX + 40, centerY);
        this.ctx.moveTo(centerX, centerY - 8);
        this.ctx.lineTo(centerX, centerY + 20);

        // Center dot
        this.ctx.fillStyle = this.colors.warning;
        this.ctx.arc(centerX, centerY, 3, 0, 2 * Math.PI);
        this.ctx.fill();
        this.ctx.stroke();
    }

    drawLeftInstrumentTape() {
        const x = 60, y = 200, width = 80, height = 200;
        const airspeed = Math.sqrt(Math.pow(this.telemetryData.groundspeed || 0, 2));

        // Professional tape background
        this.drawInstrumentPanel(x - 10, y, width, height);

        // Airspeed label and value with professional typography
        this.drawText('AIRSPEED', x + 30, y - 15, 'bold 12px "Arial", sans-serif', this.colors.text);
        this.drawText(Math.round(airspeed).toString().padStart(3, '0'), x + 30, y + height/2, 
                     'bold 24px "Courier New", monospace', this.colors.textBright);
        this.drawText('KTS', x + 30, y + height/2 + 25, '10px "Arial", sans-serif', this.colors.textDim);
    }

    drawRightInstrumentTape() {
        const x = 660, y = 200, width = 80, height = 200;
        const altitude = this.telemetryData.alt || 0;

        // Professional tape background
        this.drawInstrumentPanel(x, y, width, height);

        // Altitude label and value with professional typography
        this.drawText('ALTITUDE', x + 40, y - 15, 'bold 12px "Arial", sans-serif', this.colors.text);
        this.drawText(Math.round(altitude).toString().padStart(4, '0'), x + 40, y + height/2,
                     'bold 24px "Courier New", monospace', this.colors.textBright);
        this.drawText('FT', x + 40, y + height/2 + 25, '10px "Arial", sans-serif', this.colors.textDim);
    }

    drawTopInstrumentPanel() {
        // Top status bar with organized layout
        this.drawInstrumentPanel(50, 20, 700, 50);

        // Flight mode (left)
        const mode = this.telemetryData.mode || 'UNKNOWN';
        this.drawText(`MODE: ${mode}`, 80, 45, 'bold 14px "Arial", sans-serif', this.colors.success);

        // Armed status (center)
        const armed = this.telemetryData.armed || false;
        const armedColor = armed ? this.colors.alert : this.colors.success;
        this.drawText(armed ? 'ARMED' : 'DISARMED', 400, 45, 'bold 16px "Arial", sans-serif', armedColor);

        // Link status (right)
        this.drawText('LINK', 650, 35, '12px "Arial", sans-serif', this.colors.textDim);
        this.drawText(this.isConnected ? 'ACTIVE' : 'LOST', 650, 55, 
                     'bold 12px "Arial", sans-serif', this.isConnected ? this.colors.success : this.colors.alert);

        // GPS time (far right)
        const now = new Date();
        const utc = now.toUTCString().split(' ')[4];
        this.drawText(`UTC: ${utc}`, 720, 45, '12px "Courier New", monospace', this.colors.text);
    }

    drawBottomInstrumentPanel() {
        // Bottom data panel
        this.drawInstrumentPanel(50, 530, 700, 50);

        // Battery status (left)
        const voltage = this.telemetryData.battery_voltage || 0;
        const remaining = this.telemetryData.battery_remaining || 0;
        let batteryColor = this.colors.success;
        if (remaining < 50) batteryColor = this.colors.warning;
        if (remaining < 20) batteryColor = this.colors.alert;

        this.drawText(`BAT: ${voltage.toFixed(1)}V ${remaining}%`, 80, 555, 'bold 14px "Arial", sans-serif', batteryColor);

        // GPS status (center-left)
        const fixType = this.telemetryData.gps_fix_type || 0;
        const sats = this.telemetryData.satellites_visible || 0;
        const gpsColor = fixType >= 3 ? this.colors.success : this.colors.warning;
        this.drawText(`GPS: ${sats} SAT`, 250, 555, 'bold 14px "Arial", sans-serif', gpsColor);

        // Ground speed (center-right)
        const groundspeed = this.telemetryData.groundspeed || 0;
        this.drawText(`GS: ${Math.round(groundspeed)} KTS`, 450, 555, 'bold 14px "Arial", sans-serif', this.colors.text);

        // Waypoint distance (right)
        this.drawText('WP: --', 650, 555, 'bold 14px "Arial", sans-serif', this.colors.textDim);
    }

    // Utility functions for professional rendering
    drawText(text, x, y, font, color) {
        this.ctx.font = font;
        this.ctx.fillStyle = color;
        this.ctx.textAlign = 'center';
        this.ctx.textBaseline = 'middle';

        // Add subtle text shadow for better readability
        this.ctx.shadowColor = 'rgba(0, 0, 0, 0.8)';
        this.ctx.shadowBlur = 2;
        this.ctx.shadowOffsetX = 1;
        this.ctx.shadowOffsetY = 1;

        this.ctx.fillText(text, x, y);

        // Clear shadow
        this.ctx.shadowColor = 'transparent';
        this.ctx.shadowBlur = 0;
        this.ctx.shadowOffsetX = 0;
        this.ctx.shadowOffsetY = 0;
    }

    drawInstrumentPanel(x, y, width, height) {
        // Professional panel with subtle gradient and border
        this.ctx.fillStyle = this.colors.panel;
        this.ctx.fillRect(x, y, width, height);

        this.ctx.strokeStyle = this.colors.accent;
        this.ctx.lineWidth = 1;
        this.ctx.strokeRect(x, y, width, height);
    }

    drawProfessionalBorder() {
        // Professional border frame
        this.ctx.strokeStyle = this.colors.accent;
        this.ctx.lineWidth = 2;
        this.ctx.strokeRect(10, 10, 780, 580);

        // Corner markers for professional appearance
        const corners = [[10, 10], [790, 10], [10, 590], [790, 590]];
        corners.forEach(([x, y]) => {
            this.ctx.fillStyle = this.colors.accent;
            this.ctx.fillRect(x - 5, y - 5, 10, 10);
        });
    }
}

// Global PFD instance
let pfd = null;

// Initialize PFD when page loads
document.addEventListener('DOMContentLoaded', function() {
    if (document.getElementById('pfd-canvas')) {
        console.log('Initializing Professional PFD...');
        pfd = new PrimaryFlightDisplay('pfd-canvas');
    }
});

