from flask_socketio import emit, join_room, leave_room
from src.utils.token_tracker import record_agent_usage


def register_socketio_events(socketio):
    """Register all SocketIO event handlers."""

    @socketio.on('connect')
    def handle_connect():
        """Handle client connection."""
        record_agent_usage('web-interface-agent', 30, 25)
        emit('connection_response', {'status': 'connected', 'message': 'WebGCS connected'})

        # Send initial status
        emit('drone_status', {
            'connected': False,
            'system_id': None,
            'heartbeat_count': 0,
            'telemetry': {}
        })

    @socketio.on('disconnect')
    def handle_disconnect():
        """Handle client disconnection."""
        record_agent_usage('web-interface-agent', 20, 15)
        print('Client disconnected from WebGCS')

    @socketio.on('connect_drone')
    def handle_connect_drone(data):
        """Handle drone connection request."""
        host = data.get('host', '127.0.0.1')
        port = data.get('port', 5678)

        record_agent_usage('web-interface-agent', 35, 30)

        # This will be connected to actual MAVLink connection later
        emit('drone_connection_result', {
            'success': False,
            'message': f'Drone connection to {host}:{port} not yet implemented',
            'host': host,
            'port': port
        })

    @socketio.on('disconnect_drone')
    def handle_disconnect_drone(data=None):
        """Handle drone disconnection request."""
        record_agent_usage('web-interface-agent', 25, 20)

        emit('drone_disconnection_result', {
            'success': False,
            'message': 'Drone disconnection not yet implemented'
        })

    @socketio.on('send_command')
    def handle_send_command(data):
        """Handle flight command from web interface."""
        command_type = data.get('command')
        params = data.get('params', {})

        record_agent_usage('web-interface-agent', 40, 35)

        # Handle different command types
        if command_type == 'arm':
            confirmed = params.get('confirmed', False)
            emit('command_result', {
                'success': True,
                'command': 'arm',
                'message': f'ARM command processed (confirmed: {confirmed})',
                'params': params
            })

        elif command_type == 'disarm':
            confirmed = params.get('confirmed', False)
            emit('command_result', {
                'success': True,
                'command': 'disarm', 
                'message': f'DISARM command processed (confirmed: {confirmed})',
                'params': params
            })

        elif command_type == 'takeoff':
            altitude = params.get('altitude', 10)
            confirmed = params.get('confirmed', False)
            emit('command_result', {
                'success': True,
                'command': 'takeoff',
                'message': f'TAKEOFF command processed to {altitude}m (confirmed: {confirmed})',
                'params': params
            })

        elif command_type == 'land':
            emit('command_result', {
                'success': True,
                'command': 'land',
                'message': 'LAND command processed',
                'params': params
            })

        elif command_type == 'rtl':
            emit('command_result', {
                'success': True, 
                'command': 'rtl',
                'message': 'RTL command processed',
                'params': params
            })

        elif command_type == 'set_mode':
            mode = params.get('mode', 'UNKNOWN')
            emit('command_result', {
                'success': True,
                'command': 'set_mode',
                'message': f'Mode change to {mode} processed',
                'params': params
            })

        elif command_type == 'goto':
